# decode a multibyte utf-8 sequence at [rsi] (first byte already >= 0x80, in al)
# out: eax = codepoint or -1, edx = length (1 on error).  clobbers r8
tsl_c_decode_utf8:
	mov r8, r9
	sub r8, rsi             # bytes available
	cmp al, 0xC2
	jb .Lbad
	cmp al, 0xE0
	jae .L3
	# 2-byte
	cmp r8, 2
	jb .Lbad
	and eax, 0x1F
	movzx r8d, byte ptr [rsi+1]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	mov edx, 2
	ret
.L3:
	cmp al, 0xF0
	jae .L4
	cmp r8, 3
	jb .Lbad
	and eax, 0x0F
	movzx r8d, byte ptr [rsi+1]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	movzx r8d, byte ptr [rsi+2]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	cmp eax, 0x800
	jb .Lbad
	lea r8d, [rax-0xD800]
	cmp r8d, 0x800
	jb .Lbad
	mov edx, 3
	ret
.L4:
	cmp al, 0xF4
	ja .Lbad
	cmp r8, 4
	jb .Lbad
	and eax, 0x07
	movzx r8d, byte ptr [rsi+1]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	movzx r8d, byte ptr [rsi+2]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	movzx r8d, byte ptr [rsi+3]
	xor r8d, 0x80
	cmp r8d, 0x40
	jae .Lbad
	shl eax, 6
	or eax, r8d
	cmp eax, 0x10000
	jb .Lbad
	cmp eax, 0x10FFFF
	ja .Lbad
	mov edx, 4
	ret
.Lbad:
	mov eax, -1
	mov edx, 1
	ret

# binary search set_contains: r8 = ranges (pairs of int32), edi = count, eax = lookahead
# out: r8d = 1/0.  clobbers rdi; preserves ecx (the accepted symbol), rdx, rsi, rax
tsl_c_set_contains:
	push rdx
	push rbx
	push rcx
	mov ecx, edi
	xor edx, edx            # index
.Lsc_loop:
	cmp ecx, 1
	jbe .Lsc_last
	mov ebx, ecx
	shr ebx, 1              # half
	lea edi, [rdx+rbx]      # mid
	cmp eax, dword ptr [r8 + rdi*8]
	jl .Lsc_lt
	cmp eax, dword ptr [r8 + rdi*8 + 4]
	jle .Lsc_yes
	mov edx, edi
.Lsc_lt:
	sub ecx, ebx
	jmp .Lsc_loop
.Lsc_last:
	cmp eax, dword ptr [r8 + rdx*8]
	jl .Lsc_no
	cmp eax, dword ptr [r8 + rdx*8 + 4]
	jg .Lsc_no
.Lsc_yes:
	mov r8d, 1
	pop rcx
	pop rbx
	pop rdx
	ret
.Lsc_no:
	xor r8d, r8d
	pop rcx
	pop rbx
	pop rdx
	ret

